package cache

import (
	"container/list"
)

// entry stores the key and value in the list nodes.
type entry struct {
	key   string
	value int
}

// LRU implements a fixed-capacity least recently used cache.
type LRU struct {
	capacity int
	items    map[string]*list.Element
	evictList *list.List
}

// NewLRU initializes a new LRU cache with the given capacity.
func NewLRU(capacity int) *LRU {
	return &LRU{
		capacity:  capacity,
		items:     make(map[string]*list.Element),
		evictList: list.New(),
	}
}

// Get retrieves a value from the cache. Returns the value and true if found,
// otherwise 0 and false. Moves the accessed item to the front.
func (c *LRU) Get(key string) (int, bool) {
	if ent, ok := c.items[key]; ok {
		c.evictList.MoveToFront(ent)
		return ent.Value.(*entry).value, true
	}
	return 0, false
}

// Put adds a value to the cache. If the key exists, updates the value and
// moves it to the front. If the cache is full, evicts the least recently used item.
func (c *LRU) Put(key string, value int) {
	if ent, ok := c.items[key]; ok {
		c.evictList.MoveToFront(ent)
		ent.Value.(*entry).value = value
		return
	}

	if c.evictList.Len() >= c.capacity && c.capacity > 0 {
		c.removeOldest()
	}

	if c.capacity > 0 {
		ent := &entry{key, value}
		element := c.evictList.PushFront(ent)
		c.items[key] = element
	}
}

// Len returns the current number of items in the cache.
func (c *LRU) Len() int {
	return c.evictList.Len()
}

// removeOldest removes the least recently used item from the cache.
func (c *LRU) removeOldest() {
	ent := c.evictList.Back()
	if ent != nil {
		c.evictList.Remove(ent)
		kv := ent.Value.(*entry)
		delete(c.items, kv.key)
	}
}
